import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.DSoq407f.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"plugin-dev/getting-started.md","filePath":"plugin-dev/getting-started.md","lastUpdated":1782304957000}'),n={name:"plugin-dev/getting-started.md"};function l(d,s,p,h,o,r){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：插件长什么样、怎么写一个最简插件、怎么让它跑起来。</p></blockquote><h2 id="插件是什么" tabindex="-1">插件是什么 <a class="header-anchor" href="#插件是什么" aria-label="Permalink to &quot;插件是什么&quot;">​</a></h2><p>插件是 V3 里提供某项功能的<strong>可安装模块</strong>——签到、积分商城、视频解析、AI 对话……都做成插件。客户在插件市场浏览、购买、安装，然后绑定到自己的机器人上即可使用。</p><p>插件基于 <a href="./../xubp/overview">XUBP 协议</a> 开发，<strong>一份代码在所有平台通用</strong>。</p><h2 id="插件目录结构" tabindex="-1">插件目录结构 <a class="header-anchor" href="#插件目录结构" aria-label="Permalink to &quot;插件目录结构&quot;">​</a></h2><p>一个插件就是一个文件夹，至少包含两个文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/your_plugin/</span></span>
<span class="line"><span>├── meta.yaml        # 插件元数据（必需）</span></span>
<span class="line"><span>├── main.py          # 插件入口，定义钩子函数（必需）</span></span>
<span class="line"><span>├── setting.json     # 可视化配置项定义（可选）</span></span>
<span class="line"><span>└── webui/           # 管理界面（可选）</span></span>
<span class="line"><span>    └── dist/</span></span>
<span class="line"><span>        └── index.html   # 自包含 HTML（内联 CSS/JS）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>文件</th><th>必需</th><th>作用</th></tr></thead><tbody><tr><td><code>meta.yaml</code></td><td>✅</td><td>声明插件的代码、名称、版本、订阅的事件等</td></tr><tr><td><code>main.py</code></td><td>✅</td><td>写处理逻辑，定义钩子函数</td></tr><tr><td><code>setting.json</code></td><td>❌</td><td>定义用户在后台填写的配置表单</td></tr><tr><td><code>webui/dist/index.html</code></td><td>❌</td><td>插件自带的管理界面</td></tr></tbody></table><h2 id="最简插件-收到-你好-就回复" tabindex="-1">最简插件：收到&quot;你好&quot;就回复 <a class="header-anchor" href="#最简插件-收到-你好-就回复" aria-label="Permalink to &quot;最简插件：收到&quot;你好&quot;就回复&quot;">​</a></h2><p><strong><code>meta.yaml</code></strong>：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">code</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hello</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你好插件</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">author</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你的名字</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">收到&quot;你好&quot;就回复</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">message.group</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">message.private</span></span></code></pre></div><p><strong><code>main.py</code></strong>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> handle_event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(context):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> context.event.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;你好&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> context.reply(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你好！我是机器人~&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>就这么多。框架会自动发现 <code>handle_event</code>，在收到群消息或私聊消息时调用它，把回复发回去。</p><h2 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h2><p>开发插件只需要一个文本编辑器，<strong>不需要本地跑起整个 V3</strong>。开发流程：</p><ol><li>按上面的结构建好插件文件夹。</li><li>写好 <code>meta.yaml</code> 和 <code>main.py</code>。</li><li>把文件夹打包成 zip（或直接上传文件夹）。</li><li>在 V3 后台 / 开发者中心上传插件。</li><li>安装到测试机器人上，发消息验证。</li></ol><div class="tip custom-block"><p class="custom-block-title">本地调试技巧</p><p><code>main.py</code> 里的钩子函数可以是普通 <code>def</code> 或 <code>async def</code>，框架自动适配。本地想验证逻辑时，可以把 <code>context</code> 用一个 mock 字典模拟，跑通核心逻辑再上传。</p></div><h2 id="钩子函数一览" tabindex="-1">钩子函数一览 <a class="header-anchor" href="#钩子函数一览" aria-label="Permalink to &quot;钩子函数一览&quot;">​</a></h2><p>插件通过定义特定名称的函数来响应事件，框架自动识别并调用：</p><table tabindex="0"><thead><tr><th>钩子</th><th>触发时机</th></tr></thead><tbody><tr><td><code>handle_event(context)</code></td><td>收到订阅的事件</td></tr><tr><td><code>handle_outgoing(context)</code></td><td>消息即将发出前（拦截器用）</td></tr><tr><td><code>handle_after_send(context)</code></td><td>消息成功发出后</td></tr><tr><td><code>handle_webui(context, action, payload)</code></td><td>插件 WebUI 前端请求</td></tr><tr><td><code>on_start(info)</code></td><td>插件进程启动</td></tr><tr><td><code>on_stop(info)</code></td><td>插件进程停止</td></tr></tbody></table><p>最常用的是 <code>handle_event</code>。其余按需实现，不写就不触发。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>声明插件信息 → <a href="./meta">meta.yaml 元数据</a></li><li>让用户能配置 → <a href="./settings">配置项 setting.json</a></li><li>写处理逻辑 → <a href="./events">处理事件</a></li><li>看全部可用接口 → <a href="./context">上下文 Context</a></li></ul>`,25)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
